// Match crates/sdocx/tests/helpers/font_collection.rs without retaining generated bytes.
export function fontCollection(fonts: Buffer[]): Buffer {
	const parts = [Buffer.alloc(12 + fonts.length * 4)];
	parts[0].write('ttcf', 0, 'ascii');
	parts[0].writeUInt32BE(0x00010000, 4);
	parts[0].writeUInt32BE(fonts.length, 8);
	let length = parts[0].length;
	for (const [index, font] of fonts.entries()) {
		const padding = (4 - length % 4) % 4;
		parts.push(Buffer.alloc(padding));
		length += padding;
		parts[0].writeUInt32BE(length, 12 + index * 4);
		const face = Buffer.from(font);
		for (let table = 0; table < face.readUInt16BE(4); table++) {
			const position = 12 + table * 16 + 8;
			face.writeUInt32BE(face.readUInt32BE(position) + length, position);
		}
		parts.push(face);
		length += face.length;
	}
	return Buffer.concat(parts);
}
